 static Object field(Class<?> c,String n)throws Exception{Field f=c.getDeclaredField(n);f.setAccessible(true);return f.get(null);}
 static long utc(String s)throws Exception{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.ROOT);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.parse(s).getTime();}
 @Test public void fractionalAndOffsetDatesHaveExactMilliseconds()throws Exception{long base=utc("2026-10-28 03:00:00");assertEquals(base+123,RowDates194.millis("2026-10-28T03:00:00.123Z"));assertEquals(base+100,RowDates194.millis("2026-10-28T03:00:00.1Z"));assertEquals(base+123,RowDates194.millis("2026-10-28T03:00:00.123999Z"));assertEquals(base,RowDates194.millis("2026-10-28 12:00:00+09:00"));assertEquals(base,RowDates194.millis("2026-10-28T12:00+0900"));assertEquals(base,RowDates194.millis("2026/10/28 12:00"));assertEquals(base,RowDates194.millis("<b>2026年10月28日 12時00分</b> 投稿"));}
 @Test public void invalidDatesDoNotSilentlyParsePrefixes(){for(String s:new String[]{"2026-02-30 12:00","2026-10-28 12:00:00+99:99","2026-10-28 25:00","2026/10-28 12:00","unknown"})assertEquals(s,0,RowDates194.millis(s));}
 @Test public void timestampCacheRemainsBoundedAndConcurrent()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(4);try{java.util.List<Future<Long>> work=new ArrayList<>();for(int i=0;i<1000;i++){final int n=i;work.add(pool.submit(()->RowDates194.millis(String.valueOf(1700000000L+n))));}for(int i=0;i<work.size();i++)assertEquals((1700000000L+i)*1000,work.get(i).get().longValue());Map<?,?> cache=(Map<?,?>)field(RowDates194.class,"PARSED");assertTrue(cache.size()<=256);}finally{pool.shutdownNow();}}
 @SuppressWarnings("unchecked") @Test public void invalidImageUrlClearsPreviouslyBoundThumbnail()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();ImageView image=new ImageView(a);TextView placeholder=new TextView(a);Bitmap b=Bitmap.createBitmap(8,8,Bitmap.Config.ARGB_8888);String url="https://example.invalid/cached.png";((android.util.LruCache<String,Bitmap>)field(ShortImages.class,"memory")).put(url,b);ShortImages.load(url,image,placeholder);assertNotNull(image.getDrawable());assertEquals(View.GONE,placeholder.getVisibility());ShortImages.load(null,image,placeholder);assertNull(image.getDrawable());assertNull(image.getTag());assertEquals(View.VISIBLE,placeholder.getVisibility());assertFalse(((Map<?,?>)field(ShortImages.class,"bindings")).containsKey(image));}
 @Test public void invalidRebindCancelsQueuedImageWorkAndListener()throws Exception{ThreadPoolExecutor pool=(ThreadPoolExecutor)field(ShortImages.class,"WORKERS");CountDownLatch busy=new CountDownLatch(3),release=new CountDownLatch(1);try{for(int i=0;i<3;i++)pool.submit(()->{busy.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(busy.await(5,TimeUnit.SECONDS));Activity a=Robolectric.buildActivity(Activity.class).setup().get();ImageView image=new ImageView(a);ShortImages.load("https://example.invalid/queued.png",image,null);assertFalse(((Map<?,?>)field(ShortImages.class,"jobs")).isEmpty());ShortImages.load("",image,null);assertTrue(((Map<?,?>)field(ShortImages.class,"jobs")).isEmpty());assertEquals(0,pool.getQueue().size());}finally{release.countDown();}}
 public static class Cycle extends ContextWrapper {Context next;Cycle(Context c){super(c);}public Context getBaseContext(){return next;}}
 @Test public void cyclicContextWrappersCannotHangImageCancellation()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();Cycle first=new Cycle(a),second=new Cycle(a);first.next=second;second.next=first;Method owner=ShortImages.class.getDeclaredMethod("owner",Context.class);owner.setAccessible(true);assertNull(owner.invoke(null,first));assertSame(a,owner.invoke(null,a));}
 @Test public void crashLeftoverThumbnailTempsAreRemovedWithoutTouchingActiveWrites()throws Exception{File root=java.nio.file.Files.createTempDirectory("image-cache").toFile(),dir=new File(root,"nicoid-thumbnails");assertTrue(dir.mkdir());File stale=new File(dir,"image-abandoned.tmp"),live=new File(dir,"image-current.tmp"),other=new File(dir,"unrelated.tmp");for(File f:new File[]{stale,live,other})try(FileOutputStream out=new FileOutputStream(f)){out.write(1);}assertTrue(stale.setLastModified(System.currentTimeMillis()-2L*24*3600000));assertTrue(other.setLastModified(stale.lastModified()));new ImageDiskCache(root).put("test",new byte[]{1,2,3});assertFalse(stale.exists());assertTrue(live.exists());assertTrue(other.exists());}
 public static class CountPath extends Path {int rewinds;public void rewind(){rewinds++;super.rewind();}}
 @Test public void graphReusesGeometryAndInvalidatesForNewDataAndBounds()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();FrameLayout root=new FrameLayout(a);SeekBar seek=new SeekBar(a);root.addView(seek,new FrameLayout.LayoutParams(300,40));a.setContentView(root);root.layout(0,0,300,100);seek.layout(0,0,300,40);CommentGraph215.Binding binding=new CommentGraph215.Binding(new Object(),root,seek,false);int[] bins=new int[180];bins[0]=2;bins[179]=7;binding.snapshot=new CommentGraph215.Snapshot("sm1",1000,bins,9);binding.syncHost();CommentGraph215.Overlay graph=binding.overlay;Field p=graph.getClass().getDeclaredField("path");p.setAccessible(true);CountPath path=new CountPath();p.set(graph,path);Canvas canvas=new Canvas(Bitmap.createBitmap(300,100,Bitmap.Config.ARGB_8888));for(int n=0;n<100;n++)graph.draw(canvas);assertEquals(1,path.rewinds);binding.snapshot=new CommentGraph215.Snapshot("sm1",1000,bins.clone(),9);graph.draw(canvas);assertEquals(2,path.rewinds);seek.setPadding(12,0,0,0);graph.draw(canvas);assertEquals(3,path.rewinds);assertEquals(7,binding.snapshot.max);seek.setAlpha(0f);graph.draw(canvas);assertEquals(3,path.rewinds);seek.setAlpha(1f);seek.setVisibility(View.INVISIBLE);graph.draw(canvas);assertEquals(3,path.rewinds);binding.dispose();}
 public static class ReleasedTexture extends SurfaceTexture {int releases;ReleasedTexture(){super(0);}public void release(){releases++;super.release();}}
 @Test public void retiredTextureHonorsDelegateReleaseOwnership(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();for(boolean delegateReleases:new boolean[]{false,true}){com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView texture=new com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView(a);ReleasedTexture spy=new ReleasedTexture();texture.surface=spy;final int[] calls={0};texture.setSurfaceTextureListener(new android.view.TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){}public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){}public boolean onSurfaceTextureDestroyed(SurfaceTexture t){calls[0]++;return delegateReleases;}public void onSurfaceTextureUpdated(SurfaceTexture t){}});MiniSession225.SurfaceKeeper keeper=new MiniSession225.SurfaceKeeper(texture);SurfaceTexture retained=keeper.saved;keeper.close();keeper.close();assertEquals(1,calls[0]);assertEquals(delegateReleases?1:0,spy.releases);if(!delegateReleases)retained.release();}}
