 @Test public void titleFilterPreservesOrderAndDoesNotRetainLargeInput()throws Exception{assertArrayEquals(new String[]{"abc","実況",".*"},ContentFilterRules.keywords("ＡＢＣ,abc,実況,.*,実況"));String large=new String(new char[6000]).replace('\0','Ａ');assertTrue(ContentFilterRules.blocked(large,new String[]{"aaa"}));assertFalse(((Map<?,?>)field(ContentFilterRules.class,"cache")).containsKey(large));assertFalse(ContentFilterRules.blocked("anything",new String[0]));}
 @Test public void waitingForTextureDoesNotPollEveryFrame(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();FrameLayout video=new FrameLayout(a);com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView texture=new com.devbrackets.android.exomedia.core.video.exo.ExoTextureVideoView(a);video.addView(texture);a.setContentView(video);MiniSession225.SurfaceKeeper keeper=new MiniSession225.SurfaceKeeper(texture);keeper.restore(video);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();int checks=texture.availabilityChecks;Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(100));assertEquals(checks,texture.availabilityChecks);assertFalse(keeper.closed);keeper.close();}
 @Test public void playbackWatcherDoesNotRetainItsWeakKeyOrDuplicateOnReattach()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();FrameLayout root=new FrameLayout(a);a.setContentView(root);PlayerIcons.attach(root);Map<?,?> watchers=(Map<?,?>)field(PlayerIcons.class,"WATCHERS");Object watcher=watchers.get(root);assertNotNull(watcher);Field owner=watcher.getClass().getDeclaredField("owner");owner.setAccessible(true);assertSame(root,((java.lang.ref.WeakReference<?>)owner.get(watcher)).get());for(Field f:watcher.getClass().getDeclaredFields())assertFalse(View.class.isAssignableFrom(f.getType()));for(int i=0;i<10;i++){a.setContentView(new FrameLayout(a));PlayerIcons.attach(root);assertSame(watcher,watchers.get(root));a.setContentView(root);PlayerIcons.attach(root);assertSame(watcher,watchers.get(root));}a.setContentView(new FrameLayout(a));((java.lang.ref.WeakReference<?>)owner.get(watcher)).clear();((Runnable)watcher).run();}

 @Test public void tabBadgesDistinguishRankingSearchAndOtherPages()throws Exception{SavedTabs227 saved=new SavedTabs227("{}");for(String[] row:new String[][]{{"https://www.nicovideo.jp/ranking/genre/all?term=hour","3","6","list","2"},{"https://nvapi.nicovideo.jp/v1/ranking/teiban/all?term=24h","3","6","list","2"},{"https://www.nicovideo.jp/search/video?keyword=総合","0","0","list","1"},{"https://www.nicovideo.jp/ranking/genre/all","3","0","list","0"},{"https://www.nicovideo.jp/ranking/genre/all","3","6","mylist","0"},{"","1","4","list","0"}}){SavedTabs227.Tab t=new SavedTabs227.Tab();t.url=row[0];t.kind=Integer.parseInt(row[1]);t.type=Integer.parseInt(row[2]);t.screen=row[3];assertEquals(Integer.parseInt(row[4]),MultiTabs227.badge(t));saved.add(t);}SavedTabs227 restored=new SavedTabs227(saved.save());assertEquals(2,MultiTabs227.badge(restored.tabs.get(0)));assertEquals(1,MultiTabs227.badge(restored.tabs.get(2)));}
 @Test public void fullscreenIconIsRestrictedToVideoActivityAndExcludesPopup(){com.sauzask.nicoid.NicoidVideoActivity a=Robolectric.buildActivity(com.sauzask.nicoid.NicoidVideoActivity.class).setup().get();FrameLayout root=new FrameLayout(a);View icon=new View(a);root.addView(icon);a.setContentView(root);a.getResources().getConfiguration().orientation=android.content.res.Configuration.ORIENTATION_PORTRAIT;assertFalse(PlayerIcons.fullscreenIcon(icon));a.getResources().getConfiguration().orientation=android.content.res.Configuration.ORIENTATION_LANDSCAPE;assertTrue(PlayerIcons.fullscreenIcon(icon));root.removeView(icon);PopupPinchLayout popup=new PopupPinchLayout(a,null);popup.addView(icon);root.addView(popup);assertFalse(PlayerIcons.fullscreenIcon(icon));Activity other=Robolectric.buildActivity(Activity.class).setup().get();other.getResources().getConfiguration().orientation=android.content.res.Configuration.ORIENTATION_LANDSCAPE;assertFalse(PlayerIcons.fullscreenIcon(new View(other)));}

 @Test public void fullscreenBottomIconsFindTheirViewThroughDrawableWrappers(){com.sauzask.nicoid.NicoidVideoActivity a=Robolectric.buildActivity(com.sauzask.nicoid.NicoidVideoActivity.class).setup().get();FrameLayout root=new FrameLayout(a);View button=new View(a);root.addView(button);a.setContentView(root);a.getResources().getConfiguration().orientation=android.content.res.Configuration.ORIENTATION_LANDSCAPE;for(String name:new String[]{"info","commentpost"}){PlayerIcons.Icon icon=new PlayerIcons.Icon(name,false);android.graphics.drawable.RippleDrawable ripple=new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(android.graphics.Color.WHITE),icon,new android.graphics.drawable.ColorDrawable(android.graphics.Color.WHITE));FullscreenViewport209.Glyph glyph=new FullscreenViewport209.Glyph(ripple);button.setBackground(glyph);assertSame(button,icon.iconOwner());assertEquals(.62f,icon.glyphScale(),.0001f);a.getResources().getConfiguration().orientation=android.content.res.Configuration.ORIENTATION_PORTRAIT;assertEquals(.82f,icon.glyphScale(),.0001f);a.getResources().getConfiguration().orientation=android.content.res.Configuration.ORIENTATION_LANDSCAPE;button.setBackground(null);}}

 @Test public void settingsPreviewReplacesOldRowsWithoutChangingSavedValues(){Revision233Test.Prefs a=Robolectric.buildActivity(Revision233Test.Prefs.class).setup().get();android.preference.PreferenceScreen screen=a.getPreferenceManager().createPreferenceScreen(a);a.setPreferenceScreen(screen);for(String key:new String[]{"player","comment","google_cast","setting_whole"}){android.preference.PreferenceCategory group=new android.preference.PreferenceCategory(a);group.setKey(key);screen.addPreference(group);}android.preference.PreferenceGroup comment=(android.preference.PreferenceGroup)a.findPreference("comment");for(String key:new String[]{"comment_size_percent","comment_alpha","comment_rows","comment_bold","comment_cast_min"}){android.preference.Preference p=new android.preference.Preference(a);p.setKey(key);comment.addPreference(p);}android.content.SharedPreferences prefs=android.preference.PreferenceManager.getDefaultSharedPreferences(a);prefs.edit().putInt("comment_size_percent",137).putBoolean("comment_bold",true).apply();SettingsTools.install(a);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();SettingsTools.finishSettings(a);android.preference.Preference editor=a.findPreference("comment_appearance_editor");assertNotNull(editor);assertSame(comment,SettingsTools.parent(screen,editor));for(String key:new String[]{"comment_size_percent","comment_alpha","comment_rows","comment_bold"})assertNull(key,a.findPreference(key));assertSame(a.findPreference("google_cast"),SettingsTools.parent(screen,a.findPreference("comment_cast_min")));assertEquals(137,prefs.getInt("comment_size_percent",0));assertTrue(prefs.getBoolean("comment_bold",false));assertNotNull(a.findPreference("player_controls_visibility_mode"));assertNotNull(a.findPreference("player_button_customization"));assertNull(a.findPreference("player_controls_outside_video"));assertNotNull(editor.getOnPreferenceClickListener());assertTrue(editor.getOnPreferenceClickListener().onPreferenceClick(editor));assertNotNull(org.robolectric.shadows.ShadowDialog.getLatestDialog());}

 @Test public void detailButtonOptionsShareOneEntryAndPreservePreferences(){Revision233Test.Prefs a=Robolectric.buildActivity(Revision233Test.Prefs.class).setup().get();
android.preference.PreferenceScreen root=a.getPreferenceManager().createPreferenceScreen(a);
a.setPreferenceScreen(root);
for(String key:new String[]{"player","comment","google_cast","setting_whole","nicoid_content_filter"}){android.preference.PreferenceCategory group=new android.preference.PreferenceCategory(a);
group.setKey(key);
root.addPreference(group);
}android.preference.PreferenceGroup other=(android.preference.PreferenceGroup)a.findPreference("nicoid_content_filter");
android.content.SharedPreferences prefs=android.preference.PreferenceManager.getDefaultSharedPreferences(a);
prefs.edit().putBoolean("video_info_follow_button",false).putBoolean("video_info_like_button",true).putBoolean("video_info_nicoad_button",false).apply();
for(String key:new String[]{"video_info_follow_button","video_info_like_button","video_info_nicoad_button"}){android.preference.CheckBoxPreference p=new android.preference.CheckBoxPreference(a);
p.setKey(key);
other.addPreference(p);
}SettingsTools.finishSettings(a);
SettingsTools.finishSettings(a);
android.preference.Preference entry=a.findPreference("video_info_follow_button");
assertNotNull(entry);
assertFalse(entry instanceof android.preference.CheckBoxPreference);
assertEquals(UiStrings.translate("動画情報欄のボタン"),entry.getTitle().toString());
assertSame(other,SettingsTools.parent(root,entry));
assertNull(a.findPreference("video_info_like_button"));
assertNull(a.findPreference("video_info_nicoad_button"));
assertFalse(prefs.getBoolean("video_info_follow_button",true));
assertTrue(prefs.getBoolean("video_info_like_button",false));
assertFalse(prefs.getBoolean("video_info_nicoad_button",true));
assertTrue(entry.getOnPreferenceClickListener().onPreferenceClick(entry));
Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();
android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();
assertNotNull(dialog);
dialog.getListView().measure(View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));dialog.getListView().layout(0,0,600,600);
assertEquals(3,dialog.getListView().getCount());
assertFalse(dialog.getListView().isItemChecked(0));
assertTrue(dialog.getListView().isItemChecked(1));
assertFalse(dialog.getListView().isItemChecked(2));
dialog.dismiss();
}

 @Test public void summariesKeepInternalStopsAndVisibilityIncludesCurrentChoice(){Revision233Test.Prefs a=Robolectric.buildActivity(Revision233Test.Prefs.class).setup().get();android.preference.PreferenceScreen root=a.getPreferenceManager().createPreferenceScreen(a);a.setPreferenceScreen(root);android.preference.PreferenceCategory group=new android.preference.PreferenceCategory(a);root.addPreference(group);android.preference.Preference p=new android.preference.Preference(a);p.setSummary("前半です。後半です。");group.addPreference(p);SettingsTools.cleanSummaries(root);assertEquals("前半です。後半です",p.getSummary());SettingsTools.VisibilityPreference v=new SettingsTools.VisibilityPreference(a);v.setSummary("通常再生時のみ");assertTrue(v.getSummary().toString().startsWith("通常再生時のみ"));assertFalse(v.getSummary().toString().endsWith("。"));v.setSummary("無効");assertTrue(v.getSummary().toString().startsWith("無効"));assertFalse(v.getSummary().toString().contains("通常再生時のみ"));}

